import fitpeaks as f
import numpy as np,joblib
from sklearn.model_selection import KFold
z=f.z;active=[0,2,3,4,5,7,10,11,12,13,14,15]
for kind in ['active','shared','shared_comp']:
 if kind=='active': f.D=np.column_stack([np.ones(300),f.cat,z[:,active],z[:,active]**2])
 if kind=='shared': f.D=np.column_stack([np.ones(300),f.cat,z[:,active],np.sum(z[:,active]**2,axis=1)])
 if kind=='shared_comp': f.D=np.column_stack([np.ones(300),f.cat,z[:,active],np.sum(z[:,active[:8]]**2,axis=1),z[:,active[8:]]**2])
 print('KIND',kind,flush=True)
 b,p=f.fit([(7,12,15)],starts=5)
 print('base coefs',b[:f.D.shape[1]],'anchors',p[[107,176]],flush=True)
 joblib.dump({'kind':kind,'active':active,'b':b,'D':f.D},'fit_'+kind+'.pkl')
 for seed in [42,17]:
  yp=np.zeros(300)
  for tr,ts in KFold(5,shuffle=True,random_state=seed).split(z):
   bb,pp=f.fit([(7,12,15)],tr=tr,starts=3,verbose=False);yp[ts]=pp[ts]
  print('CV',seed,np.mean((yp-f.y)**2)**.5,'MAE',np.mean(abs(yp-f.y)),flush=True)
